            m_reader.skipBits(32);
            m_reader.skipBits(7);
            m_reader.skipBits(m_reader.getBits(8));  // gci_reserved_zero_bit[i]
        }
        m_reader.skipBits(m_reader.getBitsLeft() % 8);  // gci_alignment_zero_bit
    }
