  }

  full_date = ecma_date_time_clip (full_date);

  *date_value_p = full_date;

#if JERRY_ESNEXT
  date_object_p->header.u.cls.u1.date_flags &= (uint8_t) ~ECMA_DATE_TZA_SET;
