       * whines about too many of them (apparently in some cases erroneously)
       * when the header is read.
       */
 if (code <= LIBPNG_ERROR_CODE && type == png_IDAT &&
         file->write_count == 8)
         type = 0; /* magic */

 return type;
 }

 else
 return file->type;
}

